import {topicMastered} from './adaptive.js';
export const blank=()=>({version:1,done:[],records:{},memory:{},cardSession:null,examSession:null,profile:{version:1,topics:{},events:[],diagnostics:[]},schemaVersion:4,visuals:{},exerciseRecords:{},days:{},exams:[],settings:{sound:false,motion:true}});
export function gradeNumeric(raw,expected,{integer=false,absTol=0,relTol=0}={}){let text=String(raw).trim().replace(',','.');if(!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i.test(text))return {valid:false,ok:false};let value=Number(text);if(!Number.isFinite(value)||!Number.isFinite(expected))return {valid:false,ok:false};let tolerance=Math.max(absTol,Math.abs(expected)*relTol);return {valid:true,ok:(!integer||Number.isInteger(value))&&Math.abs(value-expected)<=tolerance+Number.EPSILON*Math.max(1,Math.abs(expected)),value,tolerance}}
export function rank(s,total){let p=s.done.length/total;let rs=Object.values(s.profile?.topics||{});let mastered=rs.filter(topicMastered).length;return p===1&&mastered>=20&&s.exams.some(e=>e.score>=80)?'Jōnin':p>=.5&&mastered>=8&&s.exams.some(e=>e.score>=70)?'Chūnin':p>=.2&&mastered>=3?'Genin':'Học viên'}
export function answer(s,id,ok,now=Date.now()){let old=s.records[id]||{attempts:0,correct:0,streak:0};let streak=ok?old.streak+1:0;s.records[id]={attempts:old.attempts+1,correct:old.correct+(ok?1:0),streak,lastOK:ok,due:now+(ok?Math.min(14,2**(streak-1))*86400000:0)};let day=new Date(now).toLocaleDateString('en-CA',{timeZone:'Asia/Ho_Chi_Minh'});s.days[day]=(s.days[day]||0)+1;return s}
export function subnet(ip,p){let a=ip.trim().split('.');if(a.length!==4||a.some(x=>!/^\d+$/.test(x)||+x>255)||!Number.isInteger(p)||p<0||p>32)throw Error('Nhập IPv4 hợp lệ và prefix từ 0 đến 32.');let n=a.reduce((v,x)=>v*256+(+x),0),size=2**(32-p),net=Math.floor(n/size)*size,b=net+size-1;let str=x=>[24,16,8,0].map(k=>Math.floor(x/2**k)%256).join('.');return {network:str(net),broadcast:p>=31?'Không áp dụng cho /31, /32':str(b),first:str(p>=31?net:net+1),last:str(p>=31?b:b-1),hosts:p>=31?size:size-2,mask:str(2**32-size),size}}
export function fragments(total,mtu,header=20){if(![total,mtu,header].every(Number.isInteger)||header<20||header>60||header%4||total<header||total>65535||mtu<header+8)throw Error('Độ dài nguyên hợp lệ: header 20–60, bội 4; tổng ≤ 65535; MTU ≥ header + 8.');let cap=Math.floor((mtu-header)/8)*8,remaining=total-header,offset=0,rows=[];if(total<=mtu)return [{length:total,data:remaining,offset:0,mf:0}];while(remaining){let data=Math.min(cap,remaining);remaining-=data;rows.push({length:data+header,data,offset:offset/8,mf:remaining?1:0});offset+=data}return rows}
export function checksum(words,bits=16){if(![8,16].includes(bits)||!words.length||words.some(x=>!Number.isInteger(x)||x<0||x>=2**bits))throw Error('Từ dữ liệu phải nằm trong giới hạn bit.');let max=2**bits-1,sum=0;for(let w of words){sum+=w;while(sum>max)sum=(sum&max)+Math.floor(sum/(max+1))}return max-sum}
export function delay(bytes,mbps,km,speed,links,packets){if(![bytes,mbps,speed,links,packets].every(x=>Number.isFinite(x)&&x>0)||!Number.isFinite(km)||km<0||![links,packets].every(Number.isInteger))throw Error('Kích thước, tốc độ, số liên kết và số gói phải dương; số liên kết/gói là số nguyên.');let tx=bytes*8/(mbps*1e6),prop=km*1000/speed;return {tx,prop,one:links*(tx+prop),all:(links+packets-1)*tx+links*prop}}
export function shortest(edges,start){let nodes=[...new Set(edges.flatMap(e=>e.slice(0,2)))],dist=Object.fromEntries(nodes.map(n=>[n,n===start?0:Infinity])),prev=Object.create(null),seen=[],steps=[];while(seen.length<nodes.length){let u=nodes.filter(n=>!seen.includes(n)).sort((a,b)=>dist[a]-dist[b])[0];if(!Number.isFinite(dist[u]))break;seen.push(u);for(let [a,b,w] of edges){let v=a===u?b:b===u?a:null;if(v&&!seen.includes(v)&&dist[u]+w<dist[v]){dist[v]=dist[u]+w;prev[v]=u}}steps.push({u,dist:{...dist}})}return {dist,prev,steps}}
